import { StudioProApi } from "@mendix/extensions-api";
import { Model } from "../types/model/model";
import {
    MxCloudGenAIModelFields,
    MxCloudGenAIKeyImportData,
    MxCloudGenAIResourceAPIResponse,
} from "../types/model/mxCloudGenAIModel";
import { createStudioProLogger } from "../config/logger";

export const decodeAndParseKey = (key: string): MxCloudGenAIKeyImportData => {
    const decodedJson = atob(key);
    const keyData: MxCloudGenAIKeyImportData = JSON.parse(decodedJson);
    return keyData;
};

export const invokeResourceAPI =
    (studioPro: StudioProApi, model: Model) => async (): Promise<MxCloudGenAIResourceAPIResponse | string> => {
        const logger = createStudioProLogger(studioPro);
        try {
            const mxCloudGenAIModelFields = model.providerFields as MxCloudGenAIModelFields;
            if (!mxCloudGenAIModelFields.key) {
                throw new Error("Missing key.");
            }
            const keyData: MxCloudGenAIKeyImportData = decodeAndParseKey(mxCloudGenAIModelFields.key);

            const proxyUrl: string = await studioPro.network.httpProxy.getProxyUrl(`${keyData.resourceBaseUrl}`);

            const response = await fetch(proxyUrl, {
                method: "GET",
                headers: {
                    "Content-Type": "application/json",
                    Accept: "*/*",
                    "x-api-key": keyData.accessToken,
                },
                credentials: "omit",
            });

            if (response.status !== 200) {
                throw new Error(`HTTP ${response.status}: ${response.statusText}`);
            }

            const responseBody: MxCloudGenAIResourceAPIResponse = await response.json();

            return responseBody;
        } catch (error) {
            logger.error("Error invoking MxCloud GenAI resource API:", error);
            return error instanceof Error ? error.message : "";
        }
    };

export const updateModelDetailsFromResourcesAPI = (
    model: Model,
    resourceResponse: MxCloudGenAIResourceAPIResponse
): Model => {
    return {
        ...model,
        name: resourceResponse?.model || model.name,
        displayName: resourceResponse
            ? resourceResponse.modelName || resourceResponse.model || model.displayName
            : model.displayName,
    };
};

export const executeConnectionTest = (studioPro: StudioProApi, model: Model) => async (): Promise<Model | string> => {
    const resourceAPIResponse = await invokeResourceAPI(studioPro, model)();

    if (typeof resourceAPIResponse === "string") {
        return resourceAPIResponse;
    }

    return updateModelDetailsFromResourcesAPI(model, resourceAPIResponse);
};
