import React from "react";

import { ProgressDialogStep, StudioProApi } from "@mendix/extensions-api";

import { Model, ModelType } from "../../../types/model/model";
import { MxCloudGenAIModelFields, MxCloudGenAIKeyImportData } from "../../../types/model/mxCloudGenAIModel";
import {
    decodeAndParseKey,
    invokeResourceAPI,
    executeConnectionTest,
    updateModelDetailsFromResourcesAPI,
} from "../../../utils/mxCloudGenAIUtils";
import { createStudioProLogger } from "../../../config/logger";

export const handleImportKeyFromPortal =
    (
        studioPro: StudioProApi,
        model: Model,
        setModel: React.Dispatch<React.SetStateAction<Model>>,
        updateModelDocument: (model: Model) => Promise<void>
    ) =>
    async () => {
        const logger = createStudioProLogger(studioPro);
        try {
            const mxCloudGenAIModelFields = model.providerFields as MxCloudGenAIModelFields;

            if (!mxCloudGenAIModelFields.keyImportHelper) {
                throw new Error("No key import data found. Please paste a valid key from the MxCloud GenAI portal.");
            }

            // Decode base64 JSON
            const keyData: MxCloudGenAIKeyImportData = decodeAndParseKey(mxCloudGenAIModelFields.keyImportHelper);

            if (keyData.type !== "TEXT_GENERATION") {
                throw new Error(
                    `Unsupported key type: ${keyData.type}. Only Text Generation keys are currently supported.`
                );
            }

            // Map JSON fields to model attributes
            const updatedMxCloudGenAIModelFields: MxCloudGenAIModelFields = {
                key: mxCloudGenAIModelFields.keyImportHelper || "",
                keyImportHelper: "",
                keyId: keyData.keyId || "",
                keyName: keyData.keyName || "",
                resourceName: keyData.name || "",
                environment: keyData.environment || "",
                deepLinkURL: keyData.deepLinkUrl || "",
            };

            const updatedModel: Model = {
                ...model,
                name: keyData.model || "",
                displayName: keyData.model || "",
                type:
                    keyData.type === "TEXT_GENERATION"
                        ? "Text generation"
                        : keyData.type === "EMBEDDINGS_GENERATION"
                          ? "Embeddings"
                          : ("" as ModelType),
                providerFields: {
                    ...updatedMxCloudGenAIModelFields,
                },
            };

            // Update UI immediately with key data
            setModel(updatedModel);
            updateModelDocument(updatedModel);

            // Fetch API response in background and update model when complete
            invokeResourceAPI(studioPro, updatedModel)().then((resourceAPIResponse) => {
                if (typeof resourceAPIResponse !== "string") {
                    const finalModel = updateModelDetailsFromResourcesAPI(updatedModel, resourceAPIResponse);
                    setModel(finalModel);
                    updateModelDocument(finalModel).catch((err) =>
                        logger.error("Failed to update model document after API response:", err)
                    );
                } else {
                    logger.warn("MxCloudGenAI resource API unavailable. Could not update model details.");
                }
            });
        } catch (error) {
            logger.error("Error during MxCloud GenAI key import:", error);
            const errorMessage = "Failed to import MxCloud GenAI model key.";
            const errorDetails = "Error during MxCloud GenAI key import: " + error;
            studioPro.ui.messageBoxes.show("error", errorMessage, errorDetails);
        }
    };

export const handleValidateKey = (model: Model): string | undefined => {
    const providerFields = model.providerFields as MxCloudGenAIModelFields;
    if (!providerFields.key && !providerFields.keyImportHelper) {
        return "Key is required.";
    }
    if (!providerFields.key) {
        return "Key wasn't imported.";
    }
    return undefined;
};

export function applyKeyImportHelperChange(
    model: Model,
    value: string,
    updateModelDocument: (model: Model) => Promise<void>
) {
    const updatedModel: Model = {
        ...model,
        providerFields: {
            ...model.providerFields,
            keyImportHelper: value,
        },
    };
    updateModelDocument(updatedModel);
    return updatedModel;
}

export async function handleTestConnection(
    studioPro: StudioProApi,
    model: Model,
    setModel: React.Dispatch<React.SetStateAction<Model>>,
    updateModelDocument: (model: Model) => Promise<void>
): Promise<boolean> {
    const steps: ProgressDialogStep[] = [
        {
            title: "Testing connection",
            description: "Testing connection",
            action: async () => {
                const result = await executeConnectionTest(studioPro, model)();

                if (typeof result === "string") {
                    return result; // Error message
                }

                // Update model if values changed
                if (result.displayName !== model.displayName || result.name !== model.name) {
                    setModel(result);
                    updateModelDocument(model);
                }

                // Update model if values changed
                if (result.displayName !== model.displayName || result.name !== model.name) {
                    setModel(result);
                    updateModelDocument(result);
                }

                return true;
            },
        },
    ];
    const progressDialogResult = await studioPro.ui.dialogs.showProgressDialog("Testing connection", steps);
    switch (progressDialogResult.result) {
        case "Success":
            return true;
        case "UserCancelled":
            return false;
        case "Failure": {
            const errorMessage = "No connection.";
            const errorDetails =
                "Make sure you are connected to the internet and check if your key still exists in the Mendix GenAI portal and try again.\n" +
                (progressDialogResult.failedStep?.error ?? "");
            studioPro.ui.messageBoxes.show("error", errorMessage, errorDetails);
            return false;
        }
    }
}
