import { Button } from "@mendix/ide-ui-components/button/Button";
import React from "react";
import { DivFlexColumn, DivFlexRow, DivFlexRowAlignStart, StyledLabel } from "./elements/formelements";
import TextAreaAutogrow from "./TextAreaAutogrow";
import styled from "styled-components";

const StyledButton = styled(Button)`
    height: 25px;
`;

interface TextAreaWithButtonProps {
    label?: string;
    ariaLabel: string;
    value: string;
    onChange?: (value: string) => void;
    buttonCaption: string;
    onClick: () => void;
    description?: string;
    readOnly?: boolean;
    hasMarginTop?: boolean;
    rows?: number;
    validate?: (value: string) => true | string | string[] | null | undefined;
    buttonDisabled?: boolean;
}

const TextAreaWithButton: React.FC<TextAreaWithButtonProps> = ({
    label,
    ariaLabel,
    value,
    onChange,
    buttonCaption,
    onClick,
    description,
    readOnly = false,
    hasMarginTop = false,
    rows = 1,
    validate,
    buttonDisabled,
}) => {
    const marginTop = hasMarginTop ? 8 : 0;
    return (
        <DivFlexRow marginTop={marginTop}>
            {label && (
                <DivFlexColumn>
                    <StyledLabel>{label}</StyledLabel>
                </DivFlexColumn>
            )}
            <DivFlexColumn fullWidth>
                <DivFlexRowAlignStart>
                    <DivFlexColumn fullWidth>
                        <TextAreaAutogrow
                            ariaLabel={ariaLabel}
                            value={value}
                            onChange={onChange}
                            description={description}
                            readOnly={readOnly}
                            rows={rows}
                            validate={validate}
                        />
                    </DivFlexColumn>
                    <StyledButton onPress={onClick} isDisabled={buttonDisabled}>
                        {buttonCaption}
                    </StyledButton>
                </DivFlexRowAlignStart>
            </DivFlexColumn>
        </DivFlexRow>
    );
};

export default TextAreaWithButton;
